package dev.cosmerearcanists.power;
import com.mojang.authlib.GameProfile;
import dev.cosmerearcanists.*;
import dev.cosmerearcanists.equipment.*;
import dev.cosmerearcanists.hemalurgy.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.GameType;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.event.entity.living.LivingDeathEvent;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class HemalurgicTraitGameTests {
    private static FakePlayer player(GameTestHelper h){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"TraitTest"));p.setGameMode(GameType.SURVIVAL);p.setPos(net.minecraft.world.phys.Vec3.atCenterOf(h.absolutePos(new BlockPos(1,8,1))));PowerAttributes.migrate(p);return p;}
    private static ItemStack equip(FakePlayer p,String metal){var s=new ItemStack(EquipmentContent.SPIKES.get(metal).get());p.setItemInHand(InteractionHand.MAIN_HAND,s);return s;}
    private static LivingDeathEvent queue(FakePlayer p,LivingEntity victim){victim.setHealth(0);var death=new LivingDeathEvent(victim,p.damageSources().playerAttack(p));HemalurgyService.capture(death);return death;}
    private static LivingEntity mob(GameTestHelper h,EntityType<? extends LivingEntity> type){return type.create(h.getLevel());}
    @GameTest(template="empty") public static void ironUsesExactPiecewiseFormulaWithoutPowerRetentionLoss(GameTestHelper h){var p=player(h);var zombie=mob(h,EntityType.ZOMBIE);var stack=equip(p,"iron");double retained=HemalurgyConfig.RETENTION.get();try{zombie.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(40);HemalurgyConfig.RETENTION.set(.1);queue(p,zombie);HemalurgyService.flush();var c=HemalurgicSpikes.contents(stack);h.assertTrue(c!=null&&c.power().equals(HemalurgicTraits.STRENGTH)&&c.strength()==15,"Iron captures25%+5 above16, not the ordinary power retention rate");h.assertTrue(PowerAttributes.baseStrength(p,"a:pewter")==0&&p.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue()==1,"The charge is a stored damage bonus, not an immediately granted Metallic Art");h.assertTrue(zombie.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue()==40,"Natural trait extraction adds no unspecified permanent stat penalty beyond the lethal hit");}finally{HemalurgyConfig.RETENTION.set(retained);HemalurgyService.flush();}h.succeed();}
    @GameTest(template="empty") public static void ironIgnoresEquipmentAndTemporaryBonusesAndSupportsPassiveMobs(GameTestHelper h){var p=player(h);var zombie=mob(h,EntityType.ZOMBIE);var attr=zombie.getAttribute(Attributes.ATTACK_DAMAGE);attr.setBaseValue(4);attr.addTransientModifier(new AttributeModifier(ResourceLocation.fromNamespaceAndPath(CosmereArcanists.MOD_ID,"trait_test_bonus"),200,AttributeModifier.Operation.ADD_VALUE));var stack=equip(p,"iron");queue(p,zombie);HemalurgyService.flush();h.assertTrue(HemalurgicSpikes.contents(stack).strength()==3,"Only unmodified base attack damage enters the strength formula");var cow=mob(h,EntityType.COW);stack=equip(p,"iron");queue(p,cow);HemalurgyService.flush();h.assertTrue(HemalurgicSpikes.contents(stack).strength()==1,"A passive mob without an attack attribute uses zero base damage and the explicit+1 term");h.succeed();}
    @GameTest(template="empty") public static void tinStoresLowerFeruchemicalSenseEffectsBasedOnMobProfile(GameTestHelper h){var p=player(h);var cow=mob(h,EntityType.COW);var bat=mob(h,EntityType.BAT);var zombie=mob(h,EntityType.ZOMBIE);var warden=mob(h,EntityType.WARDEN);var ordinary=HemalurgySources.select(cow,"tin").senses();var hearing=HemalurgySources.select(bat,"tin").senses();var hostile=HemalurgySources.select(zombie,"tin").senses();var vibration=HemalurgySources.select(warden,"tin").senses();double step=dev.cosmerearcanists.feruchemy.FeruchemyConfig.TIN_TAP_STEP.get();h.assertTrue(ordinary.maximum()>0&&hearing.hearing()>ordinary.hearing()&&hostile.hearing()>ordinary.hearing()&&vibration.hearing()>hearing.hearing(),"Bats and monsters supply more natural senses than ordinary mobs");h.assertTrue(vibration.sight()==0&&vibration.touch()>ordinary.touch()&&vibration.maximum()<step&&hearing.maximum()<step,"Warden is not given sight and every channel remains below one Feruchemical tap level");var stack=equip(p,"tin");queue(p,bat);HemalurgyService.flush();var charge=HemalurgicSpikes.contents(stack);h.assertTrue(charge!=null&&charge.power().equals(HemalurgicTraits.SENSES)&&charge.senses().equals(hearing)&&PowerAttributes.baseStrength(p,"f:tin")==0,"Killing an ordinary bat stores natural sense bonuses without granting or stealing Feruchemical tin");h.succeed();}
    @GameTest(template="empty") public static void traitPayloadsRoundTripAndLegacyPowerSpikesStillLoad(GameTestHelper h){var p=player(h);var bat=mob(h,EntityType.BAT);var stack=equip(p,"tin");queue(p,bat);HemalurgyService.flush();var charge=HemalurgicSpikes.contents(stack);var restored=ItemStack.parseOptional(h.getLevel().registryAccess(),stack.save(h.getLevel().registryAccess()));h.assertTrue(HemalurgicSpikes.contents(restored).equals(charge)&&charge.sources().getFirst().identity().equals(bat.getUUID()),"Separate sense channels and donor source persist through serialization");var donor=player(h);PowerAttributes.set(donor,"a:steel",1);var legacy=equip(p,"steel");queue(p,donor);HemalurgyService.flush();var power=HemalurgicSpikes.contents(legacy);var root=legacy.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();root.getCompound("cosmerearcanists_hemalurgic_charge").putInt("schema",1);legacy.set(DataComponents.CUSTOM_DATA,CustomData.of(root));h.assertTrue(HemalurgicSpikes.contents(legacy).equals(power),"Existing schema1 power charges remain readable");h.succeed();}
    @GameTest(template="empty") public static void configuredProfilesAndLateCanceledTraitTheftsDoNotDestroySpikes(GameTestHelper h){var p=player(h);var bat=mob(h,EntityType.BAT);var original=HemalurgyConfig.SENSE_PROFILES.get();try{HemalurgyConfig.SENSE_PROFILES.set(List.of("minecraft:bat,0.2,0.9,0.2"));var expected=HemalurgySources.select(bat,"tin").senses();double step=dev.cosmerearcanists.feruchemy.FeruchemyConfig.TIN_TAP_STEP.get();h.assertTrue(Math.abs(expected.hearing()-.9*step)<1e-9,"Server-configured entity profiles are applied");var stack=equip(p,"tin");var death=queue(p,bat);death.setCanceled(true);HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(stack),"Canceled trait extraction leaves the spike uncharged");queue(p,bat);HemalurgyConfig.SENSE_PROFILES.set(List.of("minecraft:bat,0.2,0.7,0.2"));HemalurgyService.flush();h.assertTrue(!HemalurgicSpikes.marked(stack),"Changing the profile before settlement cannot produce an inconsistent captured payload");}finally{HemalurgyConfig.SENSE_PROFILES.set(original);HemalurgyService.flush();}h.succeed();}
    @GameTest(template="empty") public static void mentalTraitsRequireLivingIntelligentHumanoids(GameTestHelper h){for(var type:List.of(EntityType.COW,EntityType.ZOMBIE,EntityType.SKELETON,EntityType.ZOMBIFIED_PIGLIN)){var e=mob(h,type);h.assertTrue(HemalurgySources.select(e,"zinc")==null&&HemalurgySources.select(e,"copper")==null,"Animals and undead do not supply mental traits");}var villager=mob(h,EntityType.VILLAGER);var brute=mob(h,EntityType.PIGLIN_BRUTE);h.assertTrue(HemalurgySources.select(brute,"zinc").strength()>HemalurgySources.select(villager,"zinc").strength(),"Stronger living humanoids give more zinc fortitude");brute.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);h.assertTrue(HemalurgySources.select(brute,"zinc").strength()==.4,"Zinc resistance caps at40%");h.succeed();}
    @GameTest(template="empty") public static void copperRollPersistsWithoutRerollOrImmediateGrant(GameTestHelper h){var p=player(h);var villager=mob(h,EntityType.VILLAGER);var stack=equip(p,"copper");queue(p,villager);HemalurgyService.flush();var charge=HemalurgicSpikes.contents(stack);h.assertTrue(charge!=null&&charge.strength()>=.05&&charge.strength()<=.25,"Copper rolls within5–25%");h.assertTrue(Math.abs(charge.cognition().memoryCapacity()-3*charge.strength())<1e-9,"Memory bonus scales up to75%");for(int i=0;i<10;i++)h.assertTrue(HemalurgicSpikes.contents(stack).equals(charge),"Reading never rerolls the spike");var restored=ItemStack.parseOptional(h.getLevel().registryAccess(),stack.save(h.getLevel().registryAccess()));h.assertTrue(HemalurgicSpikes.contents(restored).equals(charge),"Mental roll persists through item serialization");h.assertTrue(PowerAttributes.baseStrength(p,"f:copper")==0,"Extraction alone grants no implanted effects");h.succeed();}
}
